async page => {
 const out = 'design/prototypes/picsee-browser/qa';
 const results = [], errors = [], failedRequests = [];
 page.on('pageerror', e => errors.push(e.message));
 page.on('response', response => { if (response.status() >= 400) failedRequests.push({url: response.url(), status: response.status()}); });
 const assert = (condition, name) => { if (!condition) throw new Error(name); results.push({check:name,passed:true}); };
 await page.setViewportSize({width:1440,height:900});
 await page.goto('http://127.0.0.1:4311/prototypes/picsee-browser/');
 await page.getByRole('listbox',{name:'图片网格'}).waitFor();
 await page.getByRole('button',{name:'浅色主题',exact:true}).click();
 await page.evaluate(async()=>{await Promise.all([...document.images].map(i=>i.decode().catch(()=>{})));});
 assert(await page.locator('.photo-cell').count()===12,'Initial grid contains 12 photos');
 assert(await page.locator('img').evaluateAll(imgs=>imgs.every(i=>i.naturalWidth>0)),'All local sample images load');
 await page.screenshot({path:out+'/grid-light.png'});
 await page.locator('[data-photo-id="alley"]').click();
 await page.keyboard.press('Space');
 await page.getByTestId('large-viewer').waitFor();
 assert(await page.locator('.viewer-heading h1').textContent()==='DSC_0341.jpg','Space opens selected image');
 assert(await page.getByRole('button',{name:'上一张图片',exact:true}).isDisabled(),'First image has disabled previous navigation');
 await page.keyboard.press('ArrowRight');
 assert(await page.locator('.viewer-heading h1').textContent()==='DSC_0342.jpg','Right arrow advances image');
 await page.keyboard.press('ArrowLeft');
 assert(await page.locator('.viewer-heading h1').textContent()==='DSC_0341.jpg','Left arrow returns image');
 await page.keyboard.press('Escape');
 assert(await page.locator('.photo-grid').isVisible(),'Esc returns to grid');
 assert(await page.locator('[data-photo-id="alley"]').getAttribute('aria-selected')==='true','Esc preserves selection');
 assert(await page.locator('[data-photo-id="alley"]').evaluate(el=>el===document.activeElement),'Esc restores focus to selected thumbnail');
 await page.getByRole('button',{name:'山间与绿意 4',exact:true}).click();
 assert(await page.locator('.photo-cell').count()===4,'Folder sidebar filters to 4 photos');
 await page.locator('[data-photo-id="hillside"]').dblclick();
 await page.getByTestId('large-viewer').waitFor();
 assert(await page.locator('.stage-position').textContent()==='2 / 4','Double-click opens scoped folder viewer');
 await page.getByRole('button',{name:'深色主题',exact:true}).click();
 assert(await page.locator('html').getAttribute('class')==='theme-dark','Dark theme applies to viewer');
 await page.evaluate(async()=>{await Promise.all([...document.images].map(i=>i.decode().catch(()=>{})));});
 await page.screenshot({path:out+'/viewer-dark.png'});
 await page.keyboard.press('ArrowRight');await page.keyboard.press('ArrowRight');
 assert(await page.getByRole('button',{name:'下一张图片',exact:true}).isDisabled(),'Last image has disabled next navigation');
 await page.keyboard.press('ArrowRight');
 assert(await page.locator('.stage-position').textContent()==='4 / 4','Arrow at boundary does not wrap');
 await page.getByRole('button',{name:'放大图片',exact:true}).click();
 assert(await page.locator('.zoom-label').textContent()==='125%','Zoom button increases magnification');
 await page.getByRole('button',{name:'恢复适应窗口',exact:true}).click();
 assert(await page.locator('.zoom-label').textContent()==='适应窗口','Fit button resets zoom');
 await page.keyboard.press('Escape');
 await page.getByRole('button',{name:'日本 · 山海之间 12',exact:true}).click();
 const search=page.getByRole('searchbox',{name:'搜索当前文件夹'});
 await search.fill('没有这张图片');
 assert(await page.getByRole('heading',{name:'没有匹配的图片'}).isVisible(),'Search displays empty state');
 await page.keyboard.press('Space');
 assert(await search.inputValue()==='没有这张图片 ','Space while typing does not open viewer');
 await search.fill('DSC_0343');
 assert(await page.locator('.photo-cell').count()===1,'Search filters files');
 await search.fill('');await search.blur();
 await page.getByRole('combobox',{name:'排序方式'}).selectOption('date');
 assert((await page.locator('.photo-name').first().textContent())==='DSC_0351.jpg','Sort by date changes visible order');
 await page.getByRole('combobox',{name:'排序方式'}).selectOption('name');
 await page.getByRole('button',{name:'隐藏侧栏',exact:true}).click();
 assert(await page.locator('.sidebar').count()===0,'Sidebar toggle hides folder pane');
 await page.getByRole('button',{name:'显示侧栏',exact:true}).click();
 await page.getByRole('button',{name:'显示图片信息',exact:true}).click();
 assert(await page.getByRole('complementary',{name:'图片信息'}).isVisible(),'Inspector opens');
 await page.getByRole('button',{name:'关闭图片信息',exact:true}).click();
 await page.getByRole('button',{name:'键盘快捷键',exact:true}).click();
 assert(await page.getByRole('dialog').isVisible(),'Keyboard shortcut dialog opens');
 await page.keyboard.press('Escape');
 assert(await page.getByRole('dialog').count()===0,'Escape closes shortcut dialog');
 const grid=page.locator('.grid-scroll');
 await grid.evaluate(el=>el.scrollTop=el.scrollHeight);
 await page.locator('[data-photo-id="gate"]').click();
 const before=await grid.evaluate(el=>el.scrollTop);
 await page.keyboard.press('Space');await page.getByTestId('large-viewer').waitFor();await page.keyboard.press('Escape');
 const after=await grid.evaluate(el=>el.scrollTop);
 assert(Math.abs(before-after)<=2,'Grid scroll position survives viewer round-trip');
 await page.screenshot({path:out+'/grid-dark.png'});
 await page.reload();await page.locator('.photo-grid').waitFor();
 assert(await page.locator('html').getAttribute('class')==='theme-dark','Theme persists after reload');
 await page.setViewportSize({width:800,height:680});
 assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'800px layout has no horizontal document overflow');
 await page.locator('.photo-cell').first().dblclick();await page.getByTestId('large-viewer').waitFor();
 assert(await page.locator('.large-image').isVisible(),'Large viewer works at narrow viewport');
 await page.screenshot({path:out+'/viewer-narrow.png'});
 await page.keyboard.press('Escape');
 await page.setViewportSize({width:1440,height:900});
 await page.getByRole('button',{name:'浅色主题',exact:true}).click();
 assert(errors.length===0,'No browser runtime errors');assert(failedRequests.length===0,'No failed page resource requests');
 const report={timestamp:new Date().toISOString(),results,errors,failedRequests};
 return {...report,checks:results.length,passed:true};
}
